package com.aistock.gateway;
import com.aistock.common.*;import com.fasterxml.jackson.databind.ObjectMapper;import jakarta.servlet.http.HttpServletRequest;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestController public class MarketApiProxyController {
 private final MarketPublicClient client;private final ObjectMapper mapper;public MarketApiProxyController(MarketPublicClient client,ObjectMapper mapper){this.client=client;this.mapper=mapper;}
 @RequestMapping({"/api/v1/instruments","/api/v1/instruments/**"})public ResponseEntity<byte[]> proxy(HttpServletRequest r,@RequestParam Map<String,String> query){String path=r.getRequestURI();if(!"GET".equals(r.getMethod())||!ProxyHeaderPolicy.allowed("GET",path))throw new BusinessException("RESOURCE_NOT_FOUND","接口不存在",HttpStatus.NOT_FOUND);var safe=new LinkedHashMap<String,String>();for(var key:List.of("q","page","size","ids","from","to","basis","versionId"))if(query.containsKey(key))safe.put(key,query.get(key));try{var response=client.get(path.substring(8),safe,ProxyHeaderPolicy.request(r));return ResponseEntity.status(response.getStatusCode()).headers(ProxyHeaderPolicy.response(response.getHeaders())).body(response.getBody());}
 catch(feign.FeignException e){if(e.status()>=400&&e.status()<500){try{var node=mapper.readTree(e.contentUTF8());if(node.hasNonNull("code")&&node.hasNonNull("message")&&node.path("data").isNull())return ResponseEntity.status(e.status()).contentType(MediaType.APPLICATION_JSON).header("Cache-Control","no-store").body(mapper.writeValueAsBytes(ApiResponse.failure(node.path("code").asText(),node.path("message").asText(),TraceIds.normalize(r.getHeader("X-Trace-Id")))));}catch(java.io.IOException ignored){}}throw unavailable();}
 catch(RuntimeException e){throw unavailable();}}
 private BusinessException unavailable(){return new BusinessException("MARKET_SERVICE_UNAVAILABLE","行情服务暂不可用，请稍后重试",HttpStatus.SERVICE_UNAVAILABLE);}
}
